api-rate-limiting.pseudocode:
class TokenBucket:
    def __init__(self, rate, capacity):
        self.rate, self.cap = rate, capacity  # 초당 보충·최대 버스트
        self.tokens, self.last = capacity, now()

    def allow(self, cost=1):
        t = now()
        refill = (t - self.last) * self.rate  # 경과 시간만큼 보충
        self.tokens = min(self.cap, self.tokens + refill)
        self.last = t
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

buckets = {}  # 제한 단위(사용자·IP·API 키)별 버킷

def handle(key, req):
    b = buckets.setdefault(key, TokenBucket(10, 20))
    if not b.allow():
        return 429, 'Too Many Requests'  # Retry-After 안내
    return process(req)

