apriori-algorithm.pseudocode:
def apriori(transactions, min_sup):
    # transactions: frozenset 항목집합 목록
    n = len(transactions)
    def support(s):
        return sum(1 for t in transactions if s <= t) / n
    items = {frozenset([i])
             for t in transactions for i in t}
    L = {s for s in items if support(s) >= min_sup}
    result, k = set(L), 2
    while L:
        # 조인: 빈발 (k-1)-집합 두 개로 k-후보 생성
        cand = {a | b for a in L for b in L
                if len(a | b) == k}
        # 가지치기: 모든 (k-1) 부분집합이 빈발해야 유지
        cand = {c for c in cand
                if all(c - {i} in L for i in c)}
        L = {c for c in cand if support(c) >= min_sup}
        result |= L
        k += 1
    return result
